import {STEPS,STORAGE_KEY,initialState,restore,snapshot,validateStep,allErrors,parsePrice,validateProduct,complete,progressOf} from './model.mjs';
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=initialState(),errors={},password='',confirmation='',tablePage=0,productPage=0,storageOk=true,failureRequested=false;try{state=restore(localStorage.getItem(STORAGE_KEY));document.body.classList.toggle('dark',localStorage.getItem(STORAGE_KEY+'.theme')==='dark');}catch{storageOk=false;}
const money=c=>(c/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const get=path=>path.split('.').reduce((obj,k)=>obj?.[k],state);
function set(path,value){const keys=path.split('.');let o=state;keys.slice(0,-1).forEach(k=>o=o[k]);o[keys.at(-1)]=value;state.completed=false;state.done=state.done.filter(i=>i>=state.step?false:true);}
function updateProgress(){const p=progressOf(state);$("#setup-progress").value=p.count;$("#setup-progress").setAttribute("aria-valuetext",`${p.percent}% — ${p.count} de ${p.total} etapas`);$("#progress-percent").textContent=`${p.percent}%`;$("#progress-count").textContent=`${p.count} de ${p.total} etapas`;}function save(){updateProgress();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(snapshot(state)));storageOk=true;}catch{storageOk=false;}$('#draft-status').textContent=storageOk?'Rascunho salvo neste navegador':'Rascunho apenas nesta sessão';}
function input(path,label,{required=false,type='text',hint='',placeholder='',full=false,options=null}={}){let err=errors[path];return `<div class="field ${full?'full':''}"><label for="${path}">${label}${required?'<span class="required" aria-hidden="true">*</span>':''}</label>${options?`<select id="${path}" data-field="${path}" ${required?'aria-required="true"':''}>${options.map(([v,l])=>`<option value="${v}" ${String(get(path))===v?'selected':''}>${l}</option>`).join('')}</select>`:`<input id="${path}" data-field="${path}" type="${type}" value="${esc(get(path))}" placeholder="${esc(placeholder)}" ${required?'aria-required="true"':''} ${err?'aria-invalid="true"':''} ${hint||err?`aria-describedby="${path}-help"`:''} ${type==='number'?'min="1" step="1"':''} ${path==='company.document'?'inputmode="numeric"':''}>`}${hint||err?`<span id="${path}-help" class="${err?'error':'hint'}">${esc(err||hint)}</span>`:''}</div>`;}
function choice(path,title,description=''){return `<label class="choice-row"><input id="${path}" type="checkbox" data-field="${path}" ${get(path)?'checked':''}><span><strong>${title}</strong>${description?`<small>${description}</small>`:''}${errors[path]?`<span class="error">${esc(errors[path])}</span>`:''}</span></label>`;}
const support=(title,text,extra='')=>`<aside class="support"><h2>${title}</h2><p>${text}</p>${extra?`<div class="rule">${extra}</div>`:''}</aside>`;
function company(){return `<div class="layout"><section class="form-surface"><div class="field-grid">${input('company.name','Nome fantasia',{required:true,placeholder:'Como seus clientes conhecem o estabelecimento',full:true})}${input('company.document','CNPJ / CPF',{required:state.receipt.showDocument,hint:state.receipt.showDocument?'Será exibido no cupom.':'Opcional. Usado no cupom quando você escolher exibi-lo.',placeholder:'Somente números ou com pontuação'})}${input('company.phone','Telefone principal',{type:'tel',placeholder:'(00) 00000-0000'})}${input('company.legalName','Razão social',{placeholder:'Opcional'})}${input('company.stateRegistration','Inscrição estadual',{placeholder:'Opcional'})}</div><details ${errors['company.uf']?'open':''}><summary>Endereço do estabelecimento</summary><div class="field-grid">${input('company.street','Endereço',{required:state.receipt.showAddress,full:true,placeholder:'Rua ou avenida'})}${input('company.number','Número')}${input('company.extra','Complemento')}${input('company.district','Bairro')}${input('company.cep','CEP')}${input('company.city','Cidade')}${input('company.uf','UF',{placeholder:'Ex.: SP'})}</div></details></section>${support('Seu nome na comanda','O nome fantasia identifica o estabelecimento no sistema e no comprovante.','CNPJ, endereço e conteúdo impresso serão conferidos na próxima etapa. Razão social e telefone ficam no cadastro; não entram automaticamente no cupom.')} </div>`;}
function paper(){let c=state.company,r=state.receipt;const address=[c.street,c.number,c.district,[c.city,c.uf].filter(Boolean).join('/')].filter(Boolean).join(' · ');return `<div class="preview-caption"><span>Prévia do cupom</span><strong>${r.paper} mm</strong></div><div class="paper" style="${r.paper==='58'?'max-width:205px;margin:auto':''}"><div class="paper-name">${esc(c.name||'Seu estabelecimento')}</div>${r.showDocument&&c.document?`<div class="paper-center">${esc(c.document)}</div>`:''}${r.showAddress&&address?`<div class="paper-center">${esc(address)}</div>`:''}${r.header?`<p class="paper-center">${esc(r.header)}</p>`:''}<hr><strong>BALCÃO</strong><div class="band">COMANDA 01</div><div>Pedido: 0001<br>Exemplo · 29/10/2026 12:00</div><hr>${r.groupItems?'<div class="paper-row"><span>2 × Refeição</span><b>32,00</b></div>':'<div class="paper-row"><span>1 × Refeição</span><b>16,00</b></div><div class="paper-row"><span>1 × Refeição</span><b>16,00</b></div>'}${r.showNotes?'<div>Obs.: sem cebola</div>':''}<hr><div class="paper-row paper-total"><span>TOTAL</span><span>R$ 32,00</span></div>${r.footer?`<p class="paper-center">${esc(r.footer)}</p>`:''}<div class="paper-logo">Comanda<br><small>por Varthex</small></div><div class="paper-footer">Sistema de gestão</div></div><p class="preview-note">Exemplo visual. Não envia impressão. O ajuste físico depende da impressora configurada no aplicativo.</p>`;}
function receipt(){return `<div class="layout coupon-layout"><section class="form-surface"><h2>O que aparece na comanda?</h2>${choice('receipt.showDocument','Exibir CNPJ / CPF','Usar o documento cadastrado em Estabelecimento.')}${choice('receipt.showAddress','Exibir endereço','Usar o endereço cadastrado em Estabelecimento.')}${choice('receipt.groupItems','Agrupar itens iguais','Somar quantidades quando produto, preço e observação forem iguais.')}${choice('receipt.showNotes','Exibir observações dos itens','Incluir pedidos como “sem cebola”.')}<div class="field-grid subform">${input('receipt.header','Mensagem do cabeçalho',{full:true,placeholder:'Opcional'})}${input('receipt.footer','Mensagem do rodapé',{full:true,placeholder:'Opcional'})}</div><div class="inline-options"><label for="receipt.paper">Papel da prévia</label><select id="receipt.paper" data-field="receipt.paper"><option value="80" ${state.receipt.paper==='80'?'selected':''}>80 mm</option><option value="58" ${state.receipt.paper==='58'?'selected':''}>58 mm</option></select></div><p class="hint" style="margin-top:16px">A impressora poderá ser configurada depois. A faixa do número da comanda permanece em destaque.</p></section><aside class="preview-panel" id="receipt-preview">${paper()}</aside></div>`;}
function pages(kind,page,count,size=6){const total=Math.max(1,Math.ceil(count/size));return total>1?`<div class="list-pages"><button data-page="${kind}" data-delta="-1" ${page===0?'disabled':''}>Anterior</button><span>${page+1} de ${total}</span><button data-page="${kind}" data-delta="1" ${page+1>=total?'disabled':''}>Próxima</button></div>`:'';}
function service(){const t=state.service;const count=Math.max(0,Math.min(300,Number(t.tableCount)||0));tablePage=Math.min(tablePage,Math.max(0,Math.ceil(count/6)-1));return `<div class="layout"><section class="form-surface"><h2>Como você atende?<span class="required" aria-hidden="true">*</span></h2>${choice('service.counter','Balcão e comandas','Abrir comandas sem precisar vincular uma mesa.')}${choice('service.tables','Atendimento em mesas','Vincular mesas às comandas durante o atendimento.')}${errors['service.mode']?`<p class="error checkboxes-error" role="alert">${errors['service.mode']}</p>`:''}<div class="field-grid subform">${input('service.commandCount','Quantidade inicial de comandas',{required:true,type:'number',hint:'De 1 a 500. Os números começam em 1.'})}${t.tables?input('service.tableCount','Quantidade inicial de mesas',{required:true,type:'number',hint:'De 1 a 300. Os números começam em 1.'}):''}</div>${t.tables?`<div class="subform"><div class="row-title"><h2>Confira as mesas</h2><span class="tag">${count} mesas</span></div><div class="table-wrap"><table><thead><tr><th>Mesa</th><th>Identificação</th></tr></thead><tbody>${Array.from({length:Math.min(6,Math.max(0,count-tablePage*6))},(_,j)=>{const n=tablePage*6+j+1;return `<tr><td>${String(n).padStart(2,'0')}</td><td>Mesa ${String(n).padStart(2,'0')}</td></tr>`;}).join('')}</tbody></table></div>${pages('tables',tablePage,count)}</div>`:''}</section>${support('Comece pelo seu atendimento','Você pode usar mesas e balcão ao mesmo tempo. O vínculo da mesa será feito ao atender a comanda.','Esta simulação usa identificação numérica. A organização por ambientes é uma proposta futura e não foi adicionada à operação atual.')} </div>`;}
function products(){const list=state.products;productPage=Math.min(productPage,Math.max(0,Math.ceil(list.length/6)-1));return `<div class="layout"><section class="form-surface"><div class="row-title"><h2>Seus primeiros produtos</h2><span class="tag">${list.length} cadastrados</span></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>Produto</th><th>Unidade</th><th>Preço</th><th></th></tr></thead><tbody>${list.slice(productPage*6,productPage*6+6).map((p,j)=>`<tr><td>${esc(p.name)}</td><td>${esc(p.unit)}</td><td class="money">${money(p.cents)}</td><td><button class="remove" data-remove-product="${productPage*6+j}" aria-label="Remover ${esc(p.name)} do protótipo">Remover</button></td></tr>`).join('')}</tbody></table></div>${pages('products',productPage,list.length)}`:'<div class="empty">Nenhum produto adicionado. Cadastre um para experimentar ou configure depois.</div>'}<form id="product-form" class="add-form"><div class="field-grid"><div class="field full"><label for="product-name">Nome do produto<span class="required" aria-hidden="true">*</span></label><input id="product-name" name="name" aria-required="true" placeholder="Ex.: Refeição no quilo"></div><div class="field"><label for="product-unit">Unidade<span class="required" aria-hidden="true">*</span></label><select id="product-unit" name="unit" aria-required="true"><option value="UN">Unidade (UN)</option><option value="KG">Quilograma (KG)</option></select></div><div class="field"><label for="product-price">Preço de venda (R$)<span class="required" aria-hidden="true">*</span></label><input id="product-price" name="price" inputmode="decimal" aria-required="true" placeholder="0,00"></div></div><p id="product-error" class="error" role="alert" style="margin-top:10px"></p><button type="submit" class="button secondary">Adicionar produto</button></form></section>${support('Poucos produtos já bastam','Comece pelos itens mais vendidos. Você poderá completar o catálogo depois.','Os produtos inseridos aqui ficam apenas neste protótipo. Complementos e controle de estoque não são configurados nesta etapa.')} </div>`;}
function payments(){return `<div class="layout"><section class="form-surface"><h2>Formas aceitas<span class="required" aria-hidden="true">*</span></h2>${['Dinheiro','Pix','Débito','Crédito'].map(name=>`<label class="choice-row"><input type="checkbox" data-payment="${name}" ${state.payments.includes(name)?'checked':''}><span><strong>${name}</strong><small>${name==='Dinheiro'?'Registro do recebido e cálculo de troco.':name==='Pix'?'Confirmação após conferir o recebimento.':'Registro do pagamento realizado na maquininha.'}</small></span></label>`).join('')}${errors.payments?`<p class="error checkboxes-error">${errors.payments}</p>`:''}</section>${support('Você pode combinar formas','Uma mesma comanda pode receber pagamentos parciais em formas diferentes.','Esta etapa prepara a escolha dos meios. Não conecta Pix ou maquininha, não realiza cobranças e não altera as regras atuais de pagamento.')} </div>`;}
function staff(){return `<div class="layout"><section class="form-surface">${input('manager','Nome do responsável',{required:state.access,placeholder:'Quem vai administrar o estabelecimento'})}${choice('access','Preparar acesso por login e senha','Simulação da escolha de segurança. Não ativa proteção no aplicativo real.')}${state.access?`<div class="field-grid subform">${input('login','Login do responsável',{required:true,full:true,placeholder:'Ex.: gestor'})}<div class="field"><label for="manager-password">Senha<span class="required" aria-hidden="true">*</span></label><input id="manager-password" type="password" autocomplete="new-password" aria-required="true" value="${esc(password)}"><span class="${errors.password?'error':'hint'}">${esc(errors.password||'Use uma senha fictícia com pelo menos 6 caracteres.')}</span></div><div class="field"><label for="manager-confirmation">Confirmar senha<span class="required" aria-hidden="true">*</span></label><input id="manager-confirmation" type="password" autocomplete="new-password" aria-required="true" value="${esc(confirmation)}">${errors.confirmation?`<span class="error">${errors.confirmation}</span>`:''}</div></div><p class="hint" style="margin-top:15px">A senha não é salva no rascunho nem no arquivo exportado. Ao reabrir, será preciso digitá-la novamente.</p>`:'<p class="hint" style="margin-top:14px">Você pode configurar a proteção depois. Esta escolha é apenas uma simulação.</p>'}<details><summary>Adicionar colaboradores agora</summary><div id="staff-list">${state.staff.map((p,i)=>`<div class="choice-row"><span><strong>${esc(p.name)}</strong><small>${esc(p.role)} · sem acesso configurado</small></span><button class="remove" data-remove-staff="${i}">Remover</button></div>`).join('')}</div><form id="staff-form" class="add-form"><div class="field-grid"><div class="field"><label for="staff-name">Nome<span class="required" aria-hidden="true">*</span></label><input id="staff-name" name="name" aria-required="true"></div><div class="field"><label for="staff-role">Função<span class="required" aria-hidden="true">*</span></label><select id="staff-role" name="role"><option>Atendente</option><option>Supervisor</option><option>Entregador</option></select></div></div><p class="error" id="staff-error" role="alert"></p><button class="button secondary">Adicionar colaborador</button></form></details></section>${support('Cadastre sem complicar','Colaboradores podem ser cadastrados sem criar um login. E-mail não é exigido nesta simulação.','O sistema já possui funções, permissões por operação, administrador e senha mestra. Esses controles continuam no cadastro completo; este protótipo não muda sua configuração.')} </div>`;}
function review(){const c=state.company;const rows=[['Estabelecimento',`${c.name||'Nome não informado'}\n${c.document?`CNPJ / CPF: ${c.document}`:'CNPJ / CPF não informado'}`,0],['Comanda impressa',`${state.receipt.paper} mm · ${state.receipt.showDocument?'com documento':'sem documento'} · ${state.receipt.showAddress?'com endereço':'sem endereço'}\n${state.receipt.groupItems?'Itens iguais agrupados':'Itens separados'}`,1],['Atendimento',`${[state.service.counter?'Balcão':null,state.service.tables?'Mesas':null].filter(Boolean).join(' e ')||'Não selecionado'}\n${state.service.commandCount} comandas${state.service.tables?` · ${state.service.tableCount} mesas`:''}`,2],['Produtos',state.products.length?`${state.products.length} produto(s) preparados`:'Configurar depois — necessário antes da primeira venda',3],['Pagamentos',state.payments.join(', ')||'Nenhuma forma selecionada',4],['Equipe',`${state.manager||'Responsável não informado'}\n${state.access?`Acesso por login: ${state.login}`:'Proteção para configurar depois'} · ${state.staff.length} colaborador(es)`,5]];return `<div class="layout"><section class="form-surface"><div class="review-list">${rows.map(([label,text,step])=>`<div class="review-row"><strong>${label}</strong><p>${esc(text)}</p><button data-edit="${step}" aria-label="Editar ${label}">Editar</button></div>`).join('')}</div><div class="notice">Ao concluir, você confirma uma <strong>simulação</strong>. Nenhum dado será enviado ao aplicativo, nenhuma impressão será disparada e nenhuma senha será configurada.</div><label class="choice-row" style="margin-top:12px"><input type="checkbox" id="simulate-failure" ${failureRequested?'checked':''}><span><strong>Simular falha ao concluir</strong><small>Use para avaliar a mensagem e a recuperação dos dados.</small></span></label></section>${support('Confira antes de começar','Você pode voltar a qualquer etapa para ajustar os dados.','Produtos e equipe podem ficar para depois. A configuração de impressora e servidor será um próximo passo, sem bloquear este assistente.')} </div>`;}
function success(){return `<div class="success"><svg class="success-icon" viewBox="0 0 48 48" fill="none" aria-hidden="true"><circle cx="24" cy="24" r="21" stroke="currentColor" stroke-width="2"/><path d="m14 24 7 7 14-15" stroke="currentColor" stroke-width="3"/></svg><h1>Configuração simulada concluída.</h1><p class="intro">${esc(state.company.name)}, sua sequência inicial está preparada para avaliação. Os dados continuam apenas neste protótipo.</p><section class="form-surface"><h2>O que fazer depois no aplicativo?</h2><div class="review-row"><strong>Produtos</strong><p>${state.products.length?`Revisar os ${state.products.length} produtos preparados.`:'Cadastrar os produtos antes de começar a vender.'}</p></div><div class="review-row"><strong>Impressora</strong><p>Selecionar o equipamento e conferir um cupom de teste.</p></div><div class="review-row"><strong>Celular</strong><p>Se for utilizar, iniciar o servidor e seguir o guia da rede local.</p></div><div class="review-row"><strong>Primeiro atendimento</strong><p>Validar abertura de comanda, lançamento e pagamento em um ambiente de testes.</p></div></section><div class="success-actions"><button id="export" class="button primary">Baixar configuração de exemplo</button><button id="review-again" class="button secondary">Revisar simulação</button></div><p class="completed-note">O arquivo exportado não contém senhas. Não há integração automática com o aplicativo nesta versão de avaliação.</p></div>`;}
const titles=['Como seu estabelecimento se chama?','Deixe a comanda com a sua cara.','Prepare seu atendimento.','Comece pelos produtos mais vendidos.','Como seus clientes pagam?','Quem vai usar a Comanda?','Confira e comece com tranquilidade.'];
const intros=['Esses dados identificam o seu negócio. Você poderá atualizá-los depois.','Escolha o conteúdo impresso e acompanhe o exemplo ao lado.','Defina as modalidades e a quantidade inicial de comandas e mesas.','Adicione alguns itens para experimentar o cadastro. Você também pode fazer isso depois.','Selecione as formas que você utiliza no estabelecimento.','Prepare o responsável e, se quiser, adicione os primeiros colaboradores.','Revise as escolhas antes de concluir esta simulação.'];
function render(){const n=state.step;const progress=progressOf(state);$("#setup-progress").value=progress.count;$("#setup-progress").setAttribute("aria-valuetext",`${progress.percent}% — ${progress.count} de ${progress.total} etapas`);$("#progress-percent").textContent=`${progress.percent}%`;$("#progress-count").textContent=`${progress.count} de ${progress.total} etapas`;$('#steps').innerHTML=STEPS.map((name,i)=>`<button class="step ${state.done.includes(i)?'done':''}" data-step="${i}" ${i===n&&!state.completed?'aria-current="step"':''}><span class="step-number">${i+1}</span><span class="step-name">${name}</span>${state.deferred.includes(i)?'<small>Depois</small>':''}</button>`).join('');const any=Object.keys(errors).length;$('#main').innerHTML=state.completed?success():`<h1>${titles[n]}</h1><p class="intro">${intros[n]}</p>${any?`<div class="error-summary" role="alert">${errors._global||'Confira os campos indicados para continuar.'}</div>`:''}${[company,receipt,service,products,payments,staff,review][n]()}`;$('#back').hidden=n===0||state.completed;$('#skip').hidden=![3,5].includes(n)||state.completed;$('#next').hidden=state.completed;$('#progress').textContent=`Etapa ${n+1} de ${STEPS.length}`;$('#next').textContent=n===6?'Concluir simulação':'Continuar';$('#theme').textContent=document.body.classList.contains('dark')?'Tema claro':'Tema escuro';bind();save();}
function passwordErrors(){if(!state.access)return{};const e={};if(password.length<6)e.password='Digite uma senha fictícia com pelo menos 6 caracteres.';if(confirmation!==password)e.confirmation='As senhas precisam ser iguais.';return e;}
function go(step,validate=true){if(validate){errors={...validateStep(state,state.step),...(state.step===5?passwordErrors():{})};if(Object.keys(errors).length){render();const invalid=document.querySelector('[aria-invalid=true]')||document.querySelector('.error');invalid?.focus?.();return;}state.done=[...new Set([...state.done,state.step])];}errors={};state.step=step;state.completed=false;render();$('#main').focus();window.scrollTo(0,0);}
function bind(){$('#simulate-failure')?.addEventListener('change',e=>failureRequested=e.target.checked);document.querySelectorAll('[data-field]').forEach(el=>{const path=el.dataset.field;const event=el.type==='checkbox'||el.tagName==='SELECT'?'change':'input';el.addEventListener(event,()=>{set(path,el.type==='checkbox'?el.checked:el.value);delete errors[path];save();if(el.type==='checkbox'){render();document.getElementById(path)?.focus({preventScroll:true});}else if(path.startsWith('receipt.'))$('#receipt-preview').innerHTML=paper();});if(el.type==='number')el.addEventListener('change',()=>{render();document.getElementById(path)?.focus({preventScroll:true});});});document.querySelectorAll('[data-step],[data-edit]').forEach(el=>el.onclick=()=>go(Number(el.dataset.step??el.dataset.edit),false));document.querySelectorAll('[data-payment]').forEach(el=>el.onchange=()=>{const name=el.dataset.payment;state.payments=el.checked?[...state.payments,name]:state.payments.filter(n=>n!==name);delete errors.payments;save();});document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{if(el.dataset.page==='tables')tablePage+=Number(el.dataset.delta);else productPage+=Number(el.dataset.delta);render();});document.querySelectorAll('[data-remove-product]').forEach(el=>el.onclick=()=>{state.products.splice(Number(el.dataset.removeProduct),1);render();});document.querySelectorAll('[data-remove-staff]').forEach(el=>el.onclick=()=>{state.staff.splice(Number(el.dataset.removeStaff),1);render();});$('#product-form')?.addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.currentTarget);const product=Object.fromEntries(f);const err=validateProduct(product,state.products);if(err){$('#product-error').textContent=err;return;}state.products.push({name:product.name.trim(),unit:product.unit,cents:parsePrice(product.price)});state.deferred=state.deferred.filter(i=>i!==3);render();$('#product-name').focus();});$('#staff-form')?.addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.currentTarget),name=String(f.get('name')).trim();if(!name){$('#staff-error').textContent='Informe o nome do colaborador.';return;}state.staff.push({name,role:f.get('role'),access:false,login:''});render();$('#main details').open=true;});$('#manager-password')?.addEventListener('input',e=>password=e.target.value);$('#manager-confirmation')?.addEventListener('input',e=>confirmation=e.target.value);$('#review-again')?.addEventListener('click',()=>go(6,false));$('#export')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify({tipo:'prototipo-sem-integracao',...snapshot(state)},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='comanda-configuracao-exemplo.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});}
$('#back').onclick=()=>go(state.step-1,false);$('#skip').onclick=()=>{if(state.step===5){state.access=false;password='';confirmation='';}state.deferred=[...new Set([...state.deferred,state.step])];go(state.step+1,false);};$('#next').onclick=()=>{if(state.step<6){go(state.step+1);return;}const issues=allErrors(state);const secretIssues=passwordErrors();if(issues.length){state.step=issues[0].step;errors=validateStep(state,state.step);render();$('#main').focus();return;}if(Object.keys(secretIssues).length){state.step=5;errors=secretIssues;render();return;}if(failureRequested){errors={_global:'Não foi possível concluir a simulação. Seus dados foram preservados. Desmarque a opção de falha e tente novamente.'};render();$('#main').focus();return;}const result=complete(state);if(result.ok){state=result.data;password='';confirmation='';errors={};render();$('#main').focus();window.scrollTo(0,0);}};
$('#theme').onclick=()=>{document.body.classList.toggle('dark');try{localStorage.setItem(STORAGE_KEY+'.theme',document.body.classList.contains('dark')?'dark':'light');}catch{}$('#theme').textContent=document.body.classList.contains('dark')?'Tema claro':'Tema escuro';};$('#restart').onclick=()=>$('#restart-dialog').showModal();$('#keep').onclick=()=>$('#restart-dialog').close();$('#confirm-restart').onclick=()=>{state=initialState();password='';confirmation='';errors={};failureRequested=false;tablePage=0;productPage=0;$('#restart-dialog').close();render();};render();
